window.BEHPARVAR_MBTI_SHORT_CHOICES=[["با گفت‌وگو با اعضای تیم شروع می‌کنم.","اول محیط و روش کار را مشاهده می‌کنم."],["با مثال واقعی و جزئیات شروع می‌کنم.","با مفهوم کلی و ارتباط موضوعات شروع می‌کنم."],["دلیل‌های روشن و نتیجه‌های قابل‌سنجش را بررسی می‌کنم.","ارزش‌ها و تأثیر تصمیم بر افراد را بررسی می‌کنم."],["برنامه و زمان‌بندی مشخص می‌کنم.","برنامه را برای تغییرات احتمالی باز می‌گذارم."],["کمی تنها می‌مانم تا انرژی بگیرم.","با ادامه تعامل با دیگران سرحال‌تر می‌شوم."],["به الگوها و ارتباط داده‌ها توجه می‌کنم.","به اعداد و جزئیات ثبت‌شده توجه می‌کنم."],["شرایط همکار و اثر حرفم بر رابطه را می‌سنجم.","رفتار مشخص و انتظارات کاری را روشن می‌کنم."],["گزینه‌ها را برای دریافت اطلاعات بیشتر باز می‌گذارم.","با اطلاعات کافی، زودتر تصمیم را نهایی می‌کنم."],["ایده را در گفت‌وگو شکل می‌دهم.","ایده را ابتدا در ذهن یا روی کاغذ شکل می‌دهم."],["اتفاق‌های مشخص و جزئیات را به یاد می‌آورم.","معنای کلی و درس تجربه را به یاد می‌آورم."],["از اولویت‌ها و اثربخشی کار شروع می‌کنم.","از نیاز افراد و اثر تصمیم بر آن‌ها شروع می‌کنم."],["زمان شروع و پایان جلسه را مشخص می‌کنم.","زمان‌بندی جلسه را قابل تغییر می‌گذارم."],["اول فکر می‌کنم و بعد پاسخ می‌دهم.","همان ابتدا تماس می‌گیرم یا گفت‌وگو می‌کنم."],["احتمال‌ها و ارتباط میان نشانه‌ها را دنبال می‌کنم.","واقعیت‌های هر نشانه را جداگانه بررسی می‌کنم."],["به حفظ احترام و اثر تصمیم بر افراد توجه می‌کنم.","به قوانین روشن و شواهد هر طرف توجه می‌کنم."],["راه بازنگری در تصمیم را باز می‌گذارم.","در موعد مقرر با اطلاعات موجود تصمیم می‌گیرم."],["با تعامل مستقیم با افراد مشارکت می‌کنم.","با تمرکز مستقل و عمیق مشارکت می‌کنم."],["ابتدا شواهد واقعی و مشاهدات مستقیم را بررسی می‌کنم.","ابتدا فرضیه‌ها و ارتباط علت‌ها را بررسی می‌کنم."],["منطق و شواهد پیشنهاد را می‌سنجم.","ارزش‌ها و پیامدهای انسانی پیشنهاد را می‌سنجم."],["نقش‌ها و مسئولیت‌ها را از ابتدا مشخص می‌کنم.","نقش‌ها را در طول کار شکل می‌دهم."],["گفت‌وگوی عمیق با یک یا دو نفر را انتخاب می‌کنم.","تبادل نظر با افراد بیشتر را انتخاب می‌کنم."],["امکان‌ها و کاربردهای تازه را در ذهن بررسی می‌کنم.","اجرایی‌بودن و امکانات موجود را بررسی می‌کنم."],["احساس عدالت و پذیرش افراد را می‌سنجم.","سازگاری تصمیم با قوانین و دلایل روشن را می‌سنجم."],["کارها را متناسب با وضعیت جدید دوباره می‌چینم.","به اولویت‌های برنامه اصلی برمی‌گردم."],["با افراد بیشتری رابطه کاری ایجاد می‌کنم.","روی چند رابطه کاری عمیق‌تر تمرکز می‌کنم."],["با مراحل عملی و مثال‌های واقعی شروع می‌کنم.","با اصول و مفهوم کلی مهارت شروع می‌کنم."],["توانایی اثبات‌شده و عملکرد قبلی را می‌سنجم.","ظرفیت رشد و شرایط فرد را می‌سنجم."],["روی اجرای تصمیم تصویب‌شده تمرکز می‌کنم.","امکان تغییر تصمیم با اطلاعات تازه را باز می‌گذارم."],["ابتدا نقد را با خودم مرور می‌کنم.","همان لحظه درباره نقد گفت‌وگو می‌کنم."],["بر الگوی کلی و معنای یافته‌ها تأکید می‌کنم.","بر شواهد دقیق و اتفاق‌های مشخص تأکید می‌کنم."],["شرایط فرد و ملاحظات انسانی را می‌سنجم.","اجرای منصفانه قوانین و دلیل تصمیم را می‌سنجم."],["روش را با تجربه‌کردن و اصلاح جلو می‌برم.","پیش از شروع، مراحل اصلی را مشخص می‌کنم."],["با مشارکت در بحث‌ها بهتر یاد می‌گیرم.","با گوش‌دادن و تأمل پیش از صحبت بهتر یاد می‌گیرم."],["از روش‌های موفق قبلی شروع می‌کنم.","امکان طراحی روش تازه را بررسی می‌کنم."],["نقد منطقی را روشن بیان می‌کنم.","به اثر نحوه بیان نقد بر افراد توجه می‌کنم."],["اولویت‌ها را از آغاز مرتب می‌کنم.","اولویت‌ها را بر اساس اتفاق‌ها تغییر می‌دهم."],["چند لحظه برای فکرکردن وقت می‌گیرم.","با شروع صحبت، نظرم را شکل می‌دهم."],["پیامدها و معنای احتمالی رخداد را بررسی می‌کنم.","آنچه واقعاً رخ داده را مشاهده می‌کنم."],["اثر بر افراد و ارزش‌های سازمان را می‌سنجم.","منطق تصمیم و شواهد قابل‌بررسی را می‌سنجم."],["گزینه‌ها و برنامه را از نو بررسی می‌کنم.","ابتدا چارچوب توافق‌شده را حفظ می‌کنم."],["از راه تجربه مستقیم و گفت‌وگو موضوع را می‌فهمم.","با تأمل مستقل درباره مشاهدات موضوع را می‌فهمم."],["از تجربه‌های واقعی و مشابه شروع می‌کنم.","از احتمال‌های تازه و آزموده‌نشده شروع می‌کنم."],["دلیل‌ها و شواهد طرف مقابل را بررسی می‌کنم.","نگرانی‌ها و ارزش‌های پشت نظر او را بررسی می‌کنم."],["با تصمیم، مسئول و موعد مشخص جلسه را جمع می‌کنم.","فرصت بررسی بیشتر را باز می‌گذارم."],["ابتدا مستقل کار می‌کنم و سپس نتیجه را می‌گویم.","در طول کار چند بار با همکاران تبادل نظر می‌کنم."],["الگوی مشترک و ارتباط میان روایت‌ها را پیدا می‌کنم.","جزئیات قابل تأیید هر روایت را بررسی می‌کنم."],["احترام و اثر انسانی تصمیم را در اولویت می‌گذارم.","منطق تصمیم و یکسان‌بودن قوانین را توضیح می‌دهم."],["روش انجام کار را متناسب با مانع جدید تغییر می‌دهم.","تا حد امکان روش توافق‌شده را حفظ می‌کنم."]];
